import itertools
from math import gcd

def is_good_set(U):
    n = len(U)
    if n < 3: return False
    for combo in itertools.combinations(U, 3):
        if gcd(combo[0], gcd(combo[1], combo[2])) != 1:
            return False
    for i, j in itertools.combinations(range(n), 2):
        u_i, u_j = U[i], U[j]
        found = False
        for k in range(n):
            if k != i and k != j:
                if (u_i * u_j) % U[k] == 0:
                    found = True
                    break
        if not found:
            return False
    return True

good_m = set()

# For n = 3
# We already know m = k^2 where k is not a prime power.
# Let's just search a bit to be sure.
for u1 in range(2, 100):
    for u2 in range(u1 + 1, 100):
        for u3 in range(u2 + 1, 100):
            if u1 * u2 * u3 > 1600:
                break
            if is_good_set((u1, u2, u3)):
                good_m.add(u1 * u2 * u3)

# For n = 4
# u1*u2*u3*u4 <= 1600. The largest u4 can be is 1600/(2*3*4) = 66.
for u1 in range(2, 20): # u1 must be small
    for u2 in range(u1 + 1, 40):
        for u3 in range(u2 + 1, 60):
            if u1 * u2 * u3 > 1600:
                break
            for u4 in range(u3 + 1, 1600 // (u1 * u2 * u3) + 1):
                if is_good_set((u1, u2, u3, u4)):
                    good_m.add(u1 * u2 * u3 * u4)

# For n = 5
# u1*u2*u3*u4*u5 <= 1600. The largest u5 can be is 1600/(2*3*4*5) = 13.
for U in itertools.combinations(range(2, 20), 5):
    m = 1
    for x in U: m *= x
    if m > 1600: continue
    if is_good_set(U):
        good_m.add(m)

print(sorted(list(good_m)))
